package com.johnny.hotel.cms;
import com.johnny.hotel.guest.GuestAccess;import lombok.RequiredArgsConstructor;import org.springframework.security.access.AccessDeniedException;import org.springframework.security.core.context.SecurityContextHolder;import org.springframework.stereotype.Component;import java.util.*;
@Component@RequiredArgsConstructor public class CmsAccess{private final GuestAccess access;public Long actor(){var a=SecurityContextHolder.getContext().getAuthentication();if(a==null||!(a.getDetails() instanceof Long id))throw new AccessDeniedException("CMS access denied");return id;}public Long writer(){Long id=actor();if(access.activeRoles(id).stream().noneMatch(Set.of("MANAGER","OWNER","SUPER_ADMIN")::contains))throw new AccessDeniedException("CMS write denied");return id;}public Long internal(){Long id=actor();var r=access.activeRoles(id);if(r.contains("CUSTOMER")||r.stream().noneMatch(Set.of("STAFF","MANAGER","OWNER","SUPER_ADMIN","FINANCE")::contains))throw new AccessDeniedException("Internal scene denied");return id;}}
